function translateFoodName(name, lang) {
  if (!name) return name;
  const dict = translations[lang] || translations.en;
  const dictMatch = dict[`food_${name}`];
  if (dictMatch) return dictMatch;
  return transliterateIndic(name, lang);
}
function translateNGOName(name, lang) {
  if (!name) return name;
  const dict = translations[lang] || translations.en;
  return dict[`ngo_${name}`] || name;
}
function translateNGODescription(id, defaultDesc, lang) {
  if (!defaultDesc) return void 0;
  const dict = translations[lang] || translations.en;
  return dict[`ngo_desc_${id}`] || defaultDesc;
}
function translateTag(tag, lang) {
  if (!tag) return tag;
  const dict = translations[lang] || translations.en;
  return dict[`tag_${tag}`] || tag;
}
function translateConfidence(confidence, lang) {
  if (!confidence) return confidence;
  const dict = translations[lang] || translations.en;
  const key = `confidence${confidence}`;
  return dict[key] || confidence;
}
